package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.hq.app.voidreason.VoidReasonStore;
import net.officefloor.hq.app.watch.WatchStore;
import net.officefloor.plugin.variable.Val;
import net.officefloor.plugin.variable.Out;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.PathVariable;

/** Settles each selected claim, in list order: its people by their positions, a person's
 *  claims newest first. Each goes through the very steps of a single settle by the user (period,
 *  clerk limit, opened-by, edited-by and status checks, then store, log and audit), so a clerk's settle above
 *  the clerk limit sends it to PENDING, which counts as settled. A claim that is not on the sheet,
 *  or that a single settle would refuse (every claim on an archived sheet), is refused.
 *  All or nothing: when any is refused, none is settled, every one counts as refused and nothing is
 *  stored or audited. Otherwise the bulk settle takes the sheet's next batch, each settled claim records
 *  it, and after the claims' own records BATCH_SETTLED sheet=<id> by=<user> batch=<n> count=<claims>
 *  total=<the frozen figures of those SETTLED, added up> is written. */
public class SettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettleInput input, ClaimStore store,
            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, RoleStore roles,
            RateStore rates, ClaimLogStore log, RollupService rollups, Audit audit, WatchStore watches,
            VoidReasonStore voidReasons, PlatformTransactionManager transactions,
            Out<BulkSettleResult> result) {
        String sheet = sheetId.trim();
        Map<Long, Integer> personOrder = new HashMap<>();
        // A person's claims newest first, as listed: a claim moved to them is listed as their newest.
        Map<Long, Integer> listed = new HashMap<>();
        for (Claim claim : store.list(sheet)) {
            listed.put(claim.getId(), listed.size());
        }
        for (Person person : people.list(sheet)) {
            personOrder.put(person.getId(), personOrder.size());
        }
        int refused = 0;
        List<Claim> selected = new ArrayList<>();
        for (Long id : input.claimIds()) {
            Claim claim = id == null ? null : store.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                .thenComparing(c -> listed.getOrDefault(c.getId(), Integer.MAX_VALUE)));
        StatusInput status = new StatusInput(ClaimStatus.SETTLED, input.user(), false, "");
        int all = input.claimIds().size();
        if (refused > 0) {
            result.set(new BulkSettleResult(0, all));
            return;
        }
        // All or nothing: the claims are settled in a nested transaction, their audit records held back,
        // and the first refusal rolls every one of them back and drops the records.
        TransactionTemplate nested = new TransactionTemplate(transactions);
        nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
        audit.hold();
        boolean done = false;
        try {
            done = Boolean.TRUE.equals(nested.execute(tx -> {
                long batch = store.nextBatch(sheet);
                BigDecimal total = BigDecimal.ZERO;
                for (Claim claim : selected) {
                    try {
                        sheets.refuseArchived(sheet);
                        new CheckClaimPeriod().check(claim, periods);
                        StatusMove[] move = new StatusMove[1];
                        new CheckClerkLimit().check(status, claim, roles, settings, people, rates, sheets, store, log,
                                m -> move[0] = m);
                        Rollup before = rollups.snapshot(sheet);
                        StatusChange[] change = new StatusChange[1];
                        new ApplyStatus().apply(status, move[0], claim, store, people, rates, settings, sheets, periods,
                                voidReasons, c -> change[0] = c);
                        new SaveClaim().save(status, claim, store, log);
                        store.markBatch(claim, batch);
                        new AuditClaimStatus().audit(status, move[0], claim, change[0], before, people, audit, rollups,
                                watches);
                        if (move[0].to() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
                            total = total.add(claim.getSettledDue());
                        }
                    } catch (InvalidSheetException e) {
                        tx.setRollbackOnly();
                        return false;
                    }
                }
                audit.record("BATCH_SETTLED sheet=" + sheet + " by=" + input.user() + " batch=" + batch + " count="
                        + selected.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
                return true;
            }));
        } finally {
            if (done) {
                audit.release();
            } else {
                audit.discard();
            }
        }
        result.set(done ? new BulkSettleResult(selected.size(), 0) : new BulkSettleResult(0, all));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayStore;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.hq.app.voidreason.VoidReasonStore;
import net.officefloor.hq.app.watch.WatchStore;
import net.officefloor.plugin.variable.Val;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/** Part-settles an OPEN claim: splits the amount off it through the very steps of a split, then settles the new
 *  claim by the user through the very steps of a settle (a clerk's settle above the clerk limit sends it to PENDING).
 *  The four-eyes rules and the proof rule are judged on the original claim, before the split; the new claim, opened
 *  by the user, is not judged by them again. All or nothing: a refusal of either rolls both back and drops their
 *  audit records. */
public class ApplyPartSettle {
    public void apply(@Val SplitInput input, @Val Claim claim, ClaimStore store, PersonStore people, PeriodStore periods,
            SettingStore settings, SheetStore sheets, RoleStore roles, RateStore rates, ClaimLogStore log,
            HolidayStore holidays, RollupService rollups, Audit audit, WatchStore watches, VoidReasonStore voidReasons,
            PlatformTransactionManager transactions) throws InvalidSheetException {
        StatusInput status = new StatusInput(ClaimStatus.SETTLED, input.user(), false, "");
        TransactionTemplate nested = new TransactionTemplate(transactions);
        nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
        InvalidSheetException[] refused = new InvalidSheetException[1];
        audit.hold();
        boolean done = false;
        try {
            done = Boolean.TRUE.equals(nested.execute(tx -> {
                try {
                    String sheet = claim.getSheetId();
                    Role role = roles.find(sheet, input.user());
                    // The split, as the split button makes it.
                    new CheckClaimPeriod().check(claim, periods);
                    new CheckSplit().check(input, claim, roles, settings, sheets);
                    // The settle's own rules judged on the original claim.
                    CheckClerkLimit.refuseUnpermitted(ClaimStatus.SETTLED, sheet, role, settings);
                    if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(input.user())) {
                        throw new InvalidSheetException("The user who opened a claim cannot settle it");
                    }
                    if (claim.getEditedBy() != null && claim.getEditedBy().equals(input.user())) {
                        throw new InvalidSheetException("The user who last edited a claim cannot settle it");
                    }
                    CheckProofs.refuseUnproved(status, claim, settings, people, rates, sheets, store);
                    Rollup beforeSplit = rollups.snapshot(sheet);
                    Split[] split = new Split[1];
                    new ApplySplit().apply(input, claim, store, people, settings, sheets, periods, log, holidays,
                            s -> split[0] = s);
                    new AuditClaimSplit().audit(input, claim, split[0], beforeSplit, people, audit, rollups);
                    // The settle of the new claim, as the settle button makes it.
                    Claim into = split[0].into();
                    sheets.refuseArchived(sheet);
                    new CheckClaimPeriod().check(into, periods);
                    StatusMove move = new StatusMove(ClaimStatus.OPEN, CheckClerkLimit.overLimit(status, into,
                            role == Role.STEWARD, settings, people, rates, sheets, store)
                                    ? ClaimStatus.PENDING : ClaimStatus.SETTLED);
                    Rollup beforeSettle = rollups.snapshot(sheet);
                    StatusChange[] change = new StatusChange[1];
                    // The new claim's opener is the user, who may still settle it.
                    String openedBy = into.getOpenedBy();
                    into.setOpenedBy(null);
                    try {
                        new ApplyStatus().apply(status, move, into, store, people, rates, settings, sheets, periods,
                                voidReasons, c -> change[0] = c);
                    } finally {
                        into.setOpenedBy(openedBy);
                    }
                    new SaveClaim().save(status, into, store, log);
                    new AuditClaimStatus().audit(status, move, into, change[0], beforeSettle, people, audit, rollups,
                            watches);
                    return true;
                } catch (InvalidSheetException e) {
                    refused[0] = e;
                    tx.setRollbackOnly();
                    return false;
                }
            }));
        } finally {
            if (done) {
                audit.release();
            } else {
                audit.discard();
            }
        }
        if (refused[0] != null) {
            throw refused[0];
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Freezes the SETTLED claim again at the due it would have today as an OPEN claim bound by no
 *  statement: its person's grade rate in force on its date, rounded as the sheet's policy date has
 *  it, plus the late charge it would have now, and at least the sheet's floor (none for a correction).
 *  Stores it and logs a SETTLED line, by the user; refused when another user moved it on first. */
public class ApplyResettle {
    public void apply(@Val ResettleInput input, @Val Claim claim, ClaimStore store, ClaimLogStore log,
            PersonStore people, RateStore rates, SettingStore settings, SheetStore sheets,
            Out<Resettlement> resettlement) throws InvalidSheetException {
        if (!store.move(claim, ClaimStatus.SETTLED, ClaimStatus.SETTLED)) {
            throw new InvalidSheetException("Only a SETTLED claim can be re-settled");
        }
        String sheetId = claim.getSheetId();
        Claim open = new Claim(claim.getId(), sheetId, claim.getPersonId(), claim.getAmount(), claim.getDate(),
                claim.getNote(), ClaimStatus.OPEN, claim.getNumber(), null, claim.getOpenedBy(), false, null,
                claim.getCorrects(), claim.getDueBy());
        Person person = people.find(sheetId, claim.getPersonId());
        BigDecimal pct = person == null ? null : rates.forClaim(claim).find(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal now = Lateness.of(sheetId, settings, sheets, store, people).due(open, pct);
        BigDecimal old = claim.getSettledDue();
        claim.setSettledDue(now);
        store.save(claim);
        log.record(claim, input.user());
        resettlement.set(new Resettlement(old, now));
    }
}
